import{_ as p,r as s,o,c,e as n,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"{% props %} - October CMS - 4.x","titleTemplate":false,"description":"Twig Tag","frontmatter":{"subtitle":"Twig Tag"},"headers":[{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[{"level":3,"title":"Hyphenated Attributes","slug":"hyphenated-attributes","link":"#hyphenated-attributes","children":[]}]},{"level":2,"title":"The Attributes Variable","slug":"the-attributes-variable","link":"#the-attributes-variable","children":[{"level":3,"title":"Smart Class Merging","slug":"smart-class-merging","link":"#smart-class-merging","children":[]}]},{"level":2,"title":"Empty Props","slug":"empty-props","link":"#empty-props","children":[]},{"level":2,"title":"Default Values","slug":"default-values","link":"#default-values","children":[]},{"level":2,"title":"Working with Body Content","slug":"working-with-body-content","link":"#working-with-body-content","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/markup/tag/props.md","filePath":"4.x/markup/tag/props.md"}'),u={name:"4.x/markup/tag/props.md"};function r(k,a,d,g,h,m){const t=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[n(t),a[0]||(a[0]=l("h1",null,"{% props %}",-1)),n(e),a[1]||(a[1]=i(`<p>The <code>{% props %}</code> tag is used inside <a href="./../../cms/themes/partials.html">CMS partials</a> to declare which parameters are <strong>props</strong> (template data) and which are <strong>attributes</strong> (HTML pass-through). When this tag is present, an <code>attributes</code> variable becomes available for rendering HTML attributes on elements.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>title<span class="token punctuation">:</span> <span class="token boolean">null</span><span class="token punctuation">,</span> size<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>md<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The tag uses Twig hash syntax. Keys become template variables with their specified defaults, and any parameters passed by the caller that are <strong>not</strong> listed become part of the <code>attributes</code> bag.</p><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><p>A card partial that declares <code>title</code> as a prop and forwards everything else as HTML attributes:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token comment">{# partials/card.htm #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>title<span class="token punctuation">:</span> <span class="token boolean">null</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes<span class="token punctuation">.</span>merge<span class="token punctuation">(</span><span class="token punctuation">{</span>class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>card<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>When rendered with extra attributes:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Hello<span class="token punctuation">&quot;</span></span> class<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>mt-4<span class="token punctuation">&quot;</span></span> id<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>featured<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The output will be:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>card mt-4<span class="token punctuation">&quot;</span></span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>featured<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>Hello<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <code>title</code> parameter was declared as a prop, so it becomes a template variable. The <code>class</code> and <code>id</code> parameters were not listed, so they flow into the <code>attributes</code> bag.</p><h3 id="hyphenated-attributes"><a href="#hyphenated-attributes" class="header-anchor">#</a> Hyphenated Attributes</h3><p>Hyphenated attribute names such as <code>data-*</code> and <code>aria-*</code> can be passed directly to the partial tag and flow into the <code>attributes</code> bag like any other attribute:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Hello<span class="token punctuation">&quot;</span></span> data<span class="token operator">-</span>testid<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>featured-card<span class="token punctuation">&quot;</span></span> aria<span class="token operator">-</span>label<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Featured<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The output preserves the original attribute names:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-testid</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>featured-card<span class="token punctuation">&quot;</span></span> <span class="token attr-name">aria-label</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Featured<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>Hello<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="the-attributes-variable"><a href="#the-attributes-variable" class="header-anchor">#</a> The Attributes Variable</h2><p>The <code>attributes</code> variable is an instance of Laravel&#39;s <code>ComponentAttributeBag</code>. It supports the following methods:</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>attributes.merge({class: &#39;btn&#39;})</code></td><td>Merge defaults with smart-appending for <code>class</code> and <code>style</code></td></tr><tr><td><code>attributes.only(&#39;class&#39;, &#39;id&#39;)</code></td><td>Keep only specific attributes</td></tr><tr><td><code>attributes.except(&#39;class&#39;)</code></td><td>Exclude specific attributes</td></tr><tr><td><code>attributes.has(&#39;id&#39;)</code></td><td>Check if an attribute exists</td></tr><tr><td><code>attributes.get(&#39;id&#39;)</code></td><td>Get a single attribute value</td></tr></tbody></table></div><p>When rendered (cast to string), the bag produces HTML attribute pairs: <code>class=&quot;card mt-4&quot; id=&quot;featured&quot;</code>.</p><h3 id="smart-class-merging"><a href="#smart-class-merging" class="header-anchor">#</a> Smart Class Merging</h3><p>The <code>merge</code> method handles <code>class</code> and <code>style</code> attributes intelligently — the caller&#39;s values are appended to the defaults rather than replacing them.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes<span class="token punctuation">.</span>merge<span class="token punctuation">(</span><span class="token punctuation">{</span>class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>btn btn-primary<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span> class<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>mt-4 w-full<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    Click Me
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Output: <code>&lt;button class=&quot;btn btn-primary mt-4 w-full&quot;&gt;Click Me&lt;/button&gt;</code></p><h2 id="empty-props"><a href="#empty-props" class="header-anchor">#</a> Empty Props</h2><p>Using <code>{% props {} %}</code> with an empty hash means all parameters go to attributes. This is useful for wrapper elements that only need HTML pass-through:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="default-values"><a href="#default-values" class="header-anchor">#</a> Default Values</h2><p>Props support default values that are used when the caller does not pass the parameter:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>type<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>info<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> dismissible<span class="token punctuation">:</span> <span class="token boolean">false</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>If the caller passes <code>type=&quot;warning&quot;</code>, the <code>type</code> variable will be <code>&quot;warning&quot;</code>. If not passed, it defaults to <code>&quot;info&quot;</code>.</p><h2 id="working-with-body-content"><a href="#working-with-body-content" class="header-anchor">#</a> Working with Body Content</h2><p>The <code>{% props %}</code> tag works naturally with the existing <code>body</code> keyword on partials. The <code>body</code> parameter is automatically excluded from the attribute bag.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token comment">{# partials/ui/alert.htm #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>type<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>info<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> dismissible<span class="token punctuation">:</span> <span class="token boolean">false</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes<span class="token punctuation">.</span>merge<span class="token punctuation">(</span><span class="token punctuation">{</span>class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>alert alert-<span class="token punctuation">&#39;</span></span> <span class="token operator">~</span> type<span class="token punctuation">,</span> role<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>alert<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert-content<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> dismissible <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn-close<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-bs-dismiss</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>ui/alert<span class="token punctuation">&quot;</span></span> type<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>warning<span class="token punctuation">&quot;</span></span> dismissible<span class="token operator">=</span><span class="token boolean">true</span> class<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>mb-3<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>strong</span><span class="token punctuation">&gt;</span></span>Warning!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>strong</span><span class="token punctuation">&gt;</span></span> Something needs your attention.
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./partial.html">Partial Twig Tag</a></li><li><a href="./../../cms/themes/partials.html">CMS Partials</a></li></ul></div>`,38))])}const v=p(u,[["render",r]]);export{b as __pageData,v as default};
